import { AudioOutlined, SendOutlined, StopOutlined } from "@ant-design/icons";
import { Button, Input, Tooltip, message } from "antd";
import axios from "axios";
import React, { useEffect, useState } from "react";
import SpeechRecognition, {
    useSpeechRecognition,
} from "react-speech-recognition";
import Speech from "speak-tts";

// 优先使用环境变量，如果没有则回退到 localhost
const DOMAIN = process.env.REACT_APP_DOMAIN || "http://localhost:5001";

const ChatComponent = (props) => {
  const { handleResp, isLoading, setIsLoading } = props;

  const [searchValue, setSearchValue] = useState("");
  const [isChatModeOn, setIsChatModeOn] = useState(false); // 语音模式开关
  const [isRecording, setIsRecording] = useState(false); // 是否正在录音
  const [speech, setSpeech] = useState(null); // TTS 实例

  // === 1. 样式定义 (CSS-in-JS) ===
  const styles = {
    container: {
      display: "flex",
      alignItems: "center",
      gap: "12px",
      width: "100%",
      padding: "10px 15px", // 增加内边距
    },
    // 输入框的外壳（模拟胶囊效果）
    inputWrapper: {
      flex: 1,
      display: "flex",
      alignItems: "center",
      background: "#f5f5f5", // 浅灰背景
      borderRadius: "24px", // 圆润导角
      padding: "4px 6px 4px 20px",
      border: isChatModeOn ? "1px solid #ff4d4f" : "1px solid transparent", // 语音模式显示红框
      transition: "all 0.3s ease",
    },
    // 纯净的输入框
    input: {
      border: "none",
      background: "transparent",
      boxShadow: "none",
      flex: 1,
      fontSize: "16px",
    },
    // 麦克风按钮（呼吸灯效果在下方 CSS 定义）
    micBtn: {
      width: "48px",
      height: "48px",
      borderRadius: "50%",
      border: "none",
      display: "flex",
      alignItems: "center",
      justifyContent: "center",
      fontSize: "20px",
      cursor: "pointer",
      color: "white",
      background: isChatModeOn
        ? "linear-gradient(135deg, #ff4d4f 0%, #ff7875 100%)" // 红色渐变（录音中）
        : "linear-gradient(135deg, #1677ff 0%, #4096ff 100%)", // 蓝色渐变（普通）
      boxShadow: isChatModeOn
        ? "0 4px 15px rgba(255, 77, 79, 0.4)"
        : "0 4px 15px rgba(22, 119, 255, 0.3)",
      transition: "all 0.3s ease",
    },
  };

  // === 2. 逻辑部分 (与之前保持一致) ===
  const {
    transcript,
    listening,
    resetTranscript,
    browserSupportsSpeechRecognition,
  } = useSpeechRecognition();

  useEffect(() => {
    const initialized_speech = new Speech();
    initialized_speech
      .init({
        volume: 1,
        lang: "zh-CN",
        rate: 1,
        pitch: 1,
        splitSentences: false,
      })
      .then((data) => {
        console.log("Speech is ready", data);
        setSpeech(initialized_speech);
      })
      .catch((e) => {
        console.error("An error occured while initializing : ", e);
      });
  }, []);

  // 监听语音输入并自动发送
  useEffect(() => {
    if (isChatModeOn && !listening && transcript) {
      const currentQuery = transcript;
      resetTranscript();
      onSearch(currentQuery);
      setIsRecording(false);
    }
  }, [listening, transcript, isChatModeOn]);

  // AI 说话
  const talk = (textToSay) => {
    if (!speech) return;
    SpeechRecognition.stopListening();
    setIsRecording(false);

    speech
      .speak({
        text: textToSay,
        queue: false,
        listeners: {
          onend: () => {
            if (isChatModeOn) userStartConvo();
          },
        },
      })
      .catch((e) => console.error(e));
  };

  const userStartConvo = () => {
    resetTranscript();
    SpeechRecognition.startListening({ continuous: false, language: "zh-CN" });
    setIsRecording(true);
    message.open({
        content: "Listening...",
        icon: <AudioOutlined style={{ color: "#1677ff" }} />,
        duration: 1,
        key: 'listening-msg'
    });
  };

  // 点击麦克风按钮（切换模式）
  const toggleVoiceMode = () => {
    if (isChatModeOn) {
      // 关闭模式
      setIsChatModeOn(false);
      setIsRecording(false);
      SpeechRecognition.stopListening();
      if (speech) speech.cancel();
      message.info("Voice Mode: OFF");
    } else {
      // 开启模式
      setIsChatModeOn(true);
      userStartConvo();
      message.success("Voice Mode: ON");
    }
  };

  const onSearch = async (question) => {
    if (!question.trim()) return;
    setSearchValue("");
    setIsLoading(true);

    try {
      const response = await axios.get(`${DOMAIN}/chat`, {
        params: { question },
      });
      handleResp(question, response.data);

      if (isChatModeOn && response.data.ragAnswer) {
        talk(response.data.ragAnswer);
      }
    } catch (error) {
      console.error(`Error: ${error}`);
      handleResp(question, { error: "Failed to fetch response" });
    } finally {
      setIsLoading(false);
    }
  };

  if (!browserSupportsSpeechRecognition) {
    return <div>Browser doesn't support speech recognition.</div>;
  }

  // === 3. 渲染 UI ===
  return (
    <>
      {/* 注入一个简单的 CSS 动画，让麦克风在录音时有“呼吸”效果 */}
      <style>
        {`
          @keyframes pulse-red {
            0% { box-shadow: 0 0 0 0 rgba(255, 77, 79, 0.7); }
            70% { box-shadow: 0 0 0 10px rgba(255, 77, 79, 0); }
            100% { box-shadow: 0 0 0 0 rgba(255, 77, 79, 0); }
          }
          .recording-pulse {
            animation: pulse-red 2s infinite;
          }
        `}
      </style>

      <div style={styles.container}>
        {/* === 左侧：独立的圆形麦克风/模式切换按钮 === */}
        <Tooltip title={isChatModeOn ? "Click to Stop Voice Mode" : "Click to Start Voice Mode"}>
          <button
            style={styles.micBtn}
            onClick={toggleVoiceMode}
            className={isChatModeOn && isRecording ? "recording-pulse" : ""}
          >
            {isChatModeOn ? (
               // 如果开启了模式，显示停止图标，或者根据是否录音显示波形
               isRecording ? <AudioOutlined /> : <StopOutlined />
            ) : (
               // 默认状态显示麦克风
               <AudioOutlined />
            )}
          </button>
        </Tooltip>

        {/* === 右侧：胶囊输入框 + 发送按钮 === */}
        <div style={styles.inputWrapper}>
            <Input
              placeholder={isChatModeOn ? "Listening... (Voice Mode On)" : "Type your question..."}
              disabled={isChatModeOn} // 语音模式下禁用键盘输入，防止冲突
              value={isChatModeOn && isRecording ? transcript : searchValue}
              onChange={(e) => setSearchValue(e.target.value)}
              onPressEnter={() => !isChatModeOn && onSearch(searchValue)}
              style={styles.input}
            />

            {/* 发送按钮 (只在非语音模式，且有文字时才高亮) */}
            <Button
              type="primary"
              shape="circle"
              icon={<SendOutlined />}
              onClick={() => onSearch(searchValue)}
              disabled={isChatModeOn || !searchValue} // 语音模式或没字时禁用
              style={{ flexShrink: 0 }}
            />
        </div>
      </div>
    </>
  );
};

export default ChatComponent;
